// Lead qualifier — fetch each site (fail-safe), classify, update prospect.
// Keep this logic in sync with ../qualifier/classify.mjs (the tested copy).
const SUPABASE_URL = 'SET_SUPABASE_URL';
const KEY = 'SET_SUPABASE_SERVICE_KEY';
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const SOCIAL = ['facebook.com','m.facebook.com','fb.me','fb.com','instagram.com','instagr.am','linktr.ee','linktree.com','beacons.ai','linkin.bio','msha.ke','carrd.co','taplink.cc','lnk.bio','campsite.bio','wa.me','api.whatsapp.com','tiktok.com','x.com','twitter.com'];
const SIGS = [
  ['Fresha',[/fresha\.com/i,/\bfresha\b/i]],
  ['Booksy',[/booksy\.com/i,/\bbooksy\b/i]],
  ['Treatwell',[/treatwell\./i,/\btreatwell\b/i]],
  ['Acuity Scheduling',[/acuityscheduling\.com/i,/\bacuity\b/i]],
  ['Calendly',[/calendly\.com/i]],
  ['Setmore',[/setmore\.com/i,/\bsetmore\b/i]],
  ['SimplyBook.me',[/simplybook\.(me|it)/i,/\bsimplybook\b/i]],
  ['GlossGenius',[/glossgenius\.com/i,/\bglossgenius\b/i]],
  ['Vagaro',[/vagaro\.com/i,/\bvagaro\b/i]],
  ['Timely',[/gettimely\.com/i,/timelyapp\.com/i]],
  ['Schedulicity',[/schedulicity\.com/i,/\bschedulicity\b/i]],
  ['Picktime',[/picktime\.com/i,/\bpicktime\b/i]],
  ['10to8',[/10to8\.com/i,/\b10to8\b/i]],
  ['vcita',[/vcita\.com/i,/\bvcita\b/i]],
  ['Square Appointments',[/squareup\.com\/appointments/i,/book\.squareup\.com/i,/square appointments/i]]
];
function hostOf(u){ if(!u) return ''; let s=String(u).trim(); if(!/^https?:\/\//i.test(s)) s='http://'+s; try { return new URL(s).hostname.toLowerCase().replace(/^www\./,''); } catch(e){ return ''; } }
function isSocial(u){ const h=hostOf(u); return !!h && SOCIAL.some(s=>h===s||h.endsWith('.'+s)); }
function detect(html){ const t=String(html||''); for(const pair of SIGS){ if(pair[1].some(re=>re.test(t))) return pair[0]; } return null; }
function classify(website,html,err){
  if(!website||!String(website).trim()) return {has_website:false,has_booking_system:false,booking_platform:null,lead_temp:'hot',reason:'no_website'};
  if(isSocial(website)) return {has_website:false,has_booking_system:false,booking_platform:null,lead_temp:'hot',reason:'social_only'};
  if(err) return {has_website:true,has_booking_system:null,booking_platform:null,lead_temp:'unknown',reason:'fetch_error'};
  const p=detect(html);
  if(p) return {has_website:true,has_booking_system:true,booking_platform:p,lead_temp:'cold',reason:'booking_found'};
  return {has_website:true,has_booking_system:false,booking_platform:null,lead_temp:'warm',reason:'no_booking'};
}
const raw = $input.all().map(i=>i.json);
const items = (raw.length===1 && Array.isArray(raw[0])) ? raw[0] : raw;
const out=[];
for(const p of items){
  let res, hitNet=false;
  if(!p.website||!String(p.website).trim()||isSocial(p.website)){ res=classify(p.website); }
  else {
    let html='', err=false, url=String(p.website).trim();
    if(!/^https?:\/\//i.test(url)) url='https://'+url;
    try { const r=await this.helpers.httpRequest({ url, timeout:8000, headers:{ 'User-Agent':UA, Accept:'text/html,*/*' } }); html = (typeof r==='string') ? r : JSON.stringify(r); } catch(e){ err=true; }
    res=classify(p.website, html, err); hitNet=true;
  }
  try {
    await this.helpers.httpRequest({ method:'PATCH', url: SUPABASE_URL+'/rest/v1/prospects?id=eq.'+p.id, headers:{ apikey:KEY, Authorization:'Bearer '+KEY, 'Content-Profile':'streamline_hq', 'Content-Type':'application/json', Prefer:'return=minimal' }, body:{ has_website:res.has_website, has_booking_system:res.has_booking_system, booking_platform:res.booking_platform, lead_temp:res.lead_temp, qualified_at:new Date().toISOString() }, json:true });
  } catch(e){}
  out.push({ json: { id:p.id, business_name:p.business_name, lead_temp:res.lead_temp, booking_platform:res.booking_platform, reason:res.reason } });
  if(hitNet) await new Promise(r=>setTimeout(r,1000));
}
return out;
